import React, { useState, useEffect } from "react";
import { getExamCenters } from "../services/api";

const ViewExamCenter = () => {
  const [examCenters, setExamCenters] = useState([]);

  useEffect(() => {
    const fetchExamCenters = async () => {
      try {
        const response = await getExamCenters();
        setExamCenters(response.data);
      } catch (error) {
        console.error(error);
        alert("Failed to fetch exam centers");
      }
    };

    fetchExamCenters();
  }, []);

  return (
    <div>
      <h2>Exam Centers</h2>
      <ul>
        {examCenters.map((center) => (
          <li key={center._id}>
            <h3>{center.name}</h3>
            <p>Location: {center.location}</p>
            <p>Status: {center.status}</p>
            <p>Contact: {center.contactNumber}</p>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ViewExamCenter;
